import{_ as t,c as i,o as a,ae as n}from"./chunks/framework.ixH79I-5.js";const u=JSON.parse('{"title":"🔨 Building & Developing","description":"In v1.0.1, BetterKMR shifted from the pure vanilla experience to a more modern, Webpack-based experience. This guide will show you how to build and modify BetterKMR.","frontmatter":{"title":"🔨 Building & Developing","description":"In v1.0.1, BetterKMR shifted from the pure vanilla experience to a more modern, Webpack-based experience. This guide will show you how to build and modify BetterKMR."},"headers":[],"relativePath":"guides/building_and_developing.md","filePath":"guides/building_and_developing.md"}'),o={name:"guides/building_and_developing.md"};function s(l,e,r,d,c,h){return a(),i("div",null,e[0]||(e[0]=[n(`<h1 id="🔨-building-developing" tabindex="-1">🔨 Building &amp; Developing <a class="header-anchor" href="#🔨-building-developing" aria-label="Permalink to &quot;🔨 Building &amp; Developing&quot;">​</a></h1><p style="color:rgb(121, 121, 121);">ℹ️ <span style="font-style:italic;">This guide assumes you want to build BetterKMR from the GitHub repository and be able to modify its source code. If you do not know what this means, it&#39;s best to leave this guide.</span></p><p>In v1.0.1, BetterKMR shifted from the pure vanilla experience to a more modern, Webpack-based experience. This guide will show you how to build and modify BetterKMR.</p><h3 id="cloning-and-basic-running-building-from-the-readme" tabindex="-1">Cloning and basic running/building (from the README) <a class="header-anchor" href="#cloning-and-basic-running-building-from-the-readme" aria-label="Permalink to &quot;Cloning and basic running/building (from the README)&quot;">​</a></h3><p>To build this project, you must have <a href="https://git-scm.com/" target="_blank" rel="noreferrer">Git</a> and <a href="https://www.npmjs.com/" target="_blank" rel="noreferrer">npm</a> installed. You can use <a href="https://docs.npmjs.com/cli/v8/commands/npx" target="_blank" rel="noreferrer">npx</a> and other alternatives if you prefer. You can easily get BetterKMR up and running by building in a matter of minutes. Please note that this is intended for development purposes, and we suggest getting this extension via the Chrome Web Store otherwise. To start, just clone the repository:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git clone https://github.com/Interlabs-Official/BetterKMR.git</span></span></code></pre></div><p>Once done, change your current directory to the newly cloned one and run <code>npm install</code> to gather the required dependencies.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd BetterKMR</span></span>
<span class="line"><span>npm install</span></span></code></pre></div><p>Note that <code>npm install</code> may show a few warnings. This is fine to ignore for now. To start using an almost live-refreshable version of BetterKMR (for active developing purposes), do the following command:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npm run dev</span></span></code></pre></div><p>If you would like to build BetterKMR for browsers:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npm run build:chrome</span></span>
<span class="line"><span># or</span></span>
<span class="line"><span>npm run build:firefox</span></span>
<span class="line"><span># or for both</span></span>
<span class="line"><span>npm run build:all</span></span></code></pre></div><p>Please note that the compiled version of BetterKMR will be available in the <code>dist</code> folder. This includes the live-refreshable version as well. To learn how to import your built extension into the browser, follow <a href="/BetterKMR/docs/develop/how_to_test_new_builds#enabling-the-extension-on-chrome">this guide</a>, but instead of the zip folder, use your built <code>dist</code> folder.</p><h3 id="modifying-the-code" tabindex="-1">Modifying the code <a class="header-anchor" href="#modifying-the-code" aria-label="Permalink to &quot;Modifying the code&quot;">​</a></h3><p>To modify the code, <a href="https://code.visualstudio.com/" target="_blank" rel="noreferrer">Visual Studio Code</a> is recommended, but you can use your preferred IDE. A lot of what you need has already been covered above, but here&#39;s the folders and what purpose they have:</p><ul><li><code>src/</code> - This is where most of the tweakable code is located (e.g. themes, modules, etc.)</li><li><code>docs/</code> - This is where the documentation for BetterKMR is located (what you&#39;re reading)</li><li><code>dist/</code> - This is where the compiled version of BetterKMR is located. This includes the live-refreshable version as well.</li><li><code>details/</code> - This is where extra details are located, for example, class name tooltips.</li><li><code>frameworks/</code> - A folder containing necessary frameworks for BetterKMR to function correctly.</li><li><code>settings/</code> - Contains settings related files, such as the settings page and the code editor.</li><li><code>icon/</code> - Contains icon assets for BetterKMR.</li><li><code>assets/</code> - Contains other assets, such as theme backgrounds and misc images.</li></ul><h3 id="my-changes-aren-t-always-being-reflected" tabindex="-1">My changes aren&#39;t always being reflected! <a class="header-anchor" href="#my-changes-aren-t-always-being-reflected" aria-label="Permalink to &quot;My changes aren&#39;t always being reflected!&quot;">​</a></h3><p>If you&#39;re modifying internal code, you may notice Webpack (the bundling tool &amp; live refresher) doesn&#39;t always reflect those changes. In this case, you&#39;ll need to manually refresh the extension. This is a known issue and we&#39;re unsure if this will be fixed in the future.</p><h3 id="have-fun" tabindex="-1">Have fun! <a class="header-anchor" href="#have-fun" aria-label="Permalink to &quot;Have fun!&quot;">​</a></h3><p>Have fun messing around with the code! Remember that:</p><ul><li>The code in <code>src/</code> is designed to be modular, so you can easily add your own modules or themes. However, custom themes should really be added in Settings.</li><li>Always stick to the AGPL-3.0 license when modifying the code.</li><li>BetterKMR is intended to be a community-driven project, so if you have any ideas or suggestions, feel free to open an issue or a pull request on the GitHub repo or via our Discord server.</li></ul>`,21)]))}const g=t(o,[["render",s]]);export{u as __pageData,g as default};
